// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.ui.stateimport android.content.Contextimport android.content.pm.PackageManagerimport androidx.core.content.ContextCompatimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport com.roshan.persona.brain.memory.MemoryInterfaceimport com.roshan.persona.brain.orchestrator.BrainOrchestratorimport com.roshan.persona.brain.skill.registry.SkillRegistryimport com.roshan.persona.persona.core.BuiltInPersonasimport com.roshan.persona.security.applock.AppLockManagerimport com.roshan.persona.security.auth.AuthenticationManagerimport com.roshan.persona.security.auth.BiometricAvailabilityimport com.roshan.persona.automation.engine.AutomationEngineimport dagger.hilt.android.qualifiers.ApplicationContextimport dagger.hilt.android.lifecycle.HiltViewModelimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.updateimport kotlinx.coroutines.launchimport timber.log.Timberimport javax.inject.Inject@HiltViewModelclass NousViewModel @Inject constructor(    @ApplicationContext private val appContext: Context,    private val brainOrchestrator: BrainOrchestrator,    private val memoryInterface: MemoryInterface,    private val skillRegistry: SkillRegistry,    private val automationEngine: AutomationEngine,    private val appLockManager: AppLockManager,    private val authenticationManager: AuthenticationManager,    private val _uiStateProvider: UiStateProvider,) : ViewModel() {    val uiStateProvider: UiStateProvider get() = _uiStateProvider    data class NousUiState(        val initProgress: Float = 0f,        val initStep: String = "Initializing...",        val safeMode: Boolean = false,        val integrityVerified: Boolean? = null,        val appVersion: String = "",        val buildNumber: String = "",        val isLocked: Boolean = false,        val biometricAvailable: Boolean = false,        val attemptsRemaining: Int = 3,        val lockoutMs: Long = 0,        val personas: List<PersonaSummaryData> = emptyList(),        val activePersonaId: String = "atlas",        val activePersonaName: String = "Atlas",        val activePersonaTagline: String = "Your steadfast companion",        val isMicListening: Boolean = false,        val lastVisionResult: String? = null,        val skills: List<SkillData> = emptyList(),        val automationRules: List<AutomationRuleData> = emptyList(),        val currentRoute: String = "splash",    )    data class PersonaSummaryData(val id: String, val displayName: String, val tagline: String, val archetype: String)    data class SkillData(val id: String, val displayName: String, val category: String)    data class AutomationRuleData(val id: String, val name: String, val triggerDescription: String, val actionDescription: String, val enabled: Boolean)    private val _uiState = MutableStateFlow(NousUiState())    val uiState: StateFlow<NousUiState> = _uiState.asStateFlow()    init { initializeApp() }    private fun initializeApp() {        viewModelScope.launch {            try {                updateInit(0.1f, "Checking crash recovery...")                _uiState.update { it.copy(safeMode = checkCrashSafeMode()) }                updateInit(0.2f, "Checking app lock...")                _uiState.update { it.copy(isLocked = appLockManager.isLocked(), biometricAvailable = authenticationManager.checkBiometricAvailability() == BiometricAvailability.AVAILABLE_ENROLLED) }                updateInit(0.3f, "Loading personas...")                _uiState.update { it.copy(personas = BuiltInPersonas.ALL.map { p -> PersonaSummaryData(p.id, p.displayName, p.tagline, p.archetype.displayLabel) }) }                updateInit(0.4f, "Loading skills...")                _uiState.update { it.copy(skills = skillRegistry.getAllSkills().map { s -> SkillData(s.id, s.displayName, categorizeSkill(s.id)) }) }                updateInit(0.5f, "Loading automation rules...")                refreshAutomationRules()                updateInit(0.6f, "Refreshing brain stats...")                _uiStateProvider.refreshBrainStats()                updateInit(0.7f, "Loading memories...")                _uiStateProvider.refreshMemoryData()                updateInit(0.8f, "Finalizing...")                try {                    val pi = appContext.packageManager.getPackageInfo(appContext.packageName, 0)                    _uiState.update {                        it.copy(                            appVersion = pi.versionName ?: "0.1.0",                            buildNumber = (if (android.os.Build.VERSION.SDK_INT >= 28) pi.longVersionCode else pi.versionCode.toLong()).toString(),                        )                    }                } catch (e: Exception) {                    _uiState.update { it.copy(appVersion = "0.1.0", buildNumber = "1") }                }                updateInit(0.9f, "Verifying device integrity...")                _uiState.update { it.copy(integrityVerified = null) }                updateInit(1.0f, "Ready")                clearCrashMarkers()            } catch (e: Exception) { Timber.tag("NOUS.VM").e(e, "App initialization failed"); updateInit(1.0f, "Initialization failed — entering safe mode"); _uiState.update { it.copy(safeMode = true) } }        }    }    private fun updateInit(p: Float, s: String) { _uiState.update { it.copy(initProgress = p, initStep = s) } }    private fun checkCrashSafeMode(): Boolean {        return try {            val f = java.io.File(appContext.filesDir, "crash_markers.json")            if (!f.exists()) return false            val a = org.json.JSONArray(f.readText())            val cutoff = System.currentTimeMillis() - 300_000L            var c = 0            for (i in 0 until a.length()) {                try {                    if (a.getJSONObject(i).optLong("ts", 0L) >= cutoff) c++                } catch (e: Exception) {                    Timber.tag("NOUS.VM").w(e, "Corrupt crash marker entry")                }            }            c >= 3        } catch (e: Exception) {            Timber.tag("NOUS.VM").w(e, "Failed to read crash markers")            false        }    }    private fun clearCrashMarkers() { try { java.io.File(appContext.filesDir, "crash_markers.json").delete() } catch (e: Exception) { Timber.tag("NOUS.VM").w(e, "Failed to clear crash markers") } }    fun onSplashFinished() { _uiState.update { it.copy(currentRoute = if (it.isLocked) "app_lock" else "home") } }    fun unlockWithBiometric(activity: androidx.fragment.app.FragmentActivity) {        viewModelScope.launch {            try {                val r = authenticationManager.authenticateBiometric(activity, "Unlock NOUS", "Use your biometric to unlock", "Use PIN")                if (r is com.roshan.persona.security.auth.BiometricAuthResult.Success) {                    _uiState.update { it.copy(isLocked = false, currentRoute = "home") }                }            }            catch (e: Exception) { Timber.tag("NOUS.VM").e(e, "Biometric unlock failed") }        }    }    fun unlockWithPin(pin: String) {        viewModelScope.launch {            try { if (appLockManager.unlockPin(pin.toCharArray())) { _uiState.update { it.copy(isLocked = false, currentRoute = "home", attemptsRemaining = 3) } } else { val rem = (_uiState.value.attemptsRemaining - 1).coerceAtLeast(0); _uiState.update { it.copy(attemptsRemaining = rem) }; if (rem == 0) _uiState.update { it.copy(lockoutMs = 30_000L) } } }            catch (e: Exception) { Timber.tag("NOUS.VM").e(e, "PIN unlock failed") }        }    }    fun usePasskey() { Timber.tag("NOUS.VM").i("Passkey auth requested") }    fun selectPersona(id: String) { BuiltInPersonas.ALL.firstOrNull { it.id == id }?.let { p -> _uiState.update { it.copy(activePersonaId = p.id, activePersonaName = p.displayName, activePersonaTagline = p.tagline) }; Timber.tag("NOUS.VM").i("Persona: ${p.displayName}") } }    fun toggleMic() { if (_uiState.value.isMicListening) _uiState.update { it.copy(isMicListening = false) } else { if (!hasPermission(android.Manifest.permission.RECORD_AUDIO)) { Timber.tag("NOUS.VM").w("RECORD_AUDIO not granted"); return }; _uiState.update { it.copy(isMicListening = true) } } }    fun sendUserInput(text: String) { if (text.isBlank()) return; viewModelScope.launch { try { _uiStateProvider.sendVoiceInput(text) } catch (e: Exception) { Timber.tag("NOUS.VM").e(e, "Failed to process input") } } }    fun onSkillClick(id: String) { Timber.tag("NOUS.VM").i("Skill: $id") }    fun refreshAutomationRules() { try { _uiState.update { it.copy(automationRules = automationEngine.listRules().map { r -> AutomationRuleData(r.id, r.name, r.trigger.toString(), r.action.toString(), r.isEnabled) }) } } catch (e: Exception) { Timber.tag("NOUS.VM").e(e, "Failed to load automation rules") } }    fun toggleAutomationRule(id: String) { viewModelScope.launch { try { val r = automationEngine.listRules().firstOrNull { it.id == id }; if (r != null) { if (r.isEnabled) automationEngine.disableRule(id) else automationEngine.enableRule(id); refreshAutomationRules() } } catch (e: Exception) { Timber.tag("NOUS.VM").e(e, "Toggle failed: $id") } } }    fun createAutomation(name: String, trigger: String, action: String) { viewModelScope.launch { try { val t = com.roshan.persona.automation.parser.AutomationNlParser.parseTrigger(trigger) ?: com.roshan.persona.automation.model.AutomationTrigger.EventTrigger(com.roshan.persona.automation.model.EventType.APP_LAUNCHED, null); automationEngine.createRule(name, t, com.roshan.persona.automation.model.AutomationAction.SpeakAction(action)); refreshAutomationRules() } catch (e: Exception) { Timber.tag("NOUS.VM").e(e, "Create automation failed") } } }    fun onCapture() { if (!hasPermission(android.Manifest.permission.CAMERA)) { Timber.tag("NOUS.VM").w("CAMERA not granted"); return }; Timber.tag("NOUS.VM").i("Capture requested") }    fun onFlipCamera() { Timber.tag("NOUS.VM").i("Flip camera") }    fun setVisionResult(d: String) { _uiState.update { it.copy(lastVisionResult = d) } }    fun navigateTo(r: String) { _uiState.update { it.copy(currentRoute = r) } }    fun onSettingsEntryClick(id: String) { navigateTo("settings/$id") }    fun hasPermission(p: String): Boolean = ContextCompat.checkSelfPermission(appContext, p) == PackageManager.PERMISSION_GRANTED    private fun categorizeSkill(id: String): String = when { id.startsWith("nous_call") || id.startsWith("nous_send_sms") || id.startsWith("call") || id.startsWith("send_sms") -> "Connectivity"; id.contains("automation") -> "Automation"; id in listOf("torch", "volume", "brightness", "open_app") -> "System"; id in listOf("reminder", "alarm", "timer", "note", "calendar") -> "Productivity"; id.startsWith("web") -> "Web"; else -> "Other" }}